import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates credit note for issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, true);
  assert.equal(cn.value.number, 'CN-2026-0001');
  assert.equal(cn.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(cn.value.customerId, 'C-001');
  assert.equal(cn.value.amount, 5000);
  assert.equal(cn.value.reason, 'Discount');
  assert.equal(cn.value.date, '2026-10-08');
});

test('createCreditNote works with partially_paid invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: Math.floor(totals.total / 2), date: '2026-10-08' });

  const cn = createCreditNote(r3.value, { amount: 5000, reason: 'Discount', date: '2026-10-09' }, []);
  assert.equal(cn.ok, true);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote works with paid invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: totals.total, date: '2026-10-08' });

  const cn = createCreditNote(r3.value, { amount: 5000, reason: 'Refund', date: '2026-10-09' }, []);
  assert.equal(cn.ok, true);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote rejects draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const cn = createCreditNote(r1.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, false);
  assert.equal(cn.error, 'NOT_ISSUED');
});

test('createCreditNote rejects zero amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 0, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, false);
  assert.equal(cn.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects negative amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: -5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, false);
  assert.equal(cn.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects fractional amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000.5, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, false);
  assert.equal(cn.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects amount greater than invoice total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);

  const cn = createCreditNote(r2.value, { amount: totals.total + 1, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.ok, false);
  assert.equal(cn.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote accepts amount equal to invoice total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);

  const cn = createCreditNote(r2.value, { amount: totals.total, reason: 'Full refund', date: '2026-10-08' }, []);
  assert.equal(cn.ok, true);
  assert.equal(cn.value.amount, totals.total);
});

test('createCreditNote uses credit note number format', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.value.number.startsWith('CN-2026-'), true);
});

test('createCreditNote increments credit note counter', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value);

  const cn1 = createCreditNote(r2.value, { amount: 1000, reason: 'Discount', date: '2026-10-08' }, []);
  const cn2 = createCreditNote(r2.value, { amount: 2000, reason: 'Discount', date: '2026-10-08' }, [cn1.value.number]);
  assert.equal(cn1.value.number, 'CN-2026-0001');
  assert.equal(cn2.value.number, 'CN-2026-0002');
});

test('createCreditNote separates invoice and credit note counters', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, ['INV-2026-0099']);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, ['INV-2026-0099']);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote handles year boundary', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-12-31' }, []);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote uses date year for numbering', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2027-01-15' }, []);
  assert.equal(cn.value.number, 'CN-2027-0001');
});

test('createCreditNote with different reasons', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const reasons = ['Discount', 'Return', 'Damaged goods', 'Billing error'];
  for (const reason of reasons) {
    const cn = createCreditNote(r2.value, { amount: 1000, reason, date: '2026-10-08' }, []);
    assert.equal(cn.ok, true);
    assert.equal(cn.value.reason, reason);
  }
});

test('createCreditNote preserves invoice details', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(cn.value.customerId, 'C-001');
});

test('createCreditNote with multiple existing numbers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const existingNumbers = [
    'INV-2026-0001',
    'INV-2026-0002',
    'CN-2026-0001',
    'CN-2026-0003',
  ];

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, existingNumbers);
  assert.equal(cn.value.number, 'CN-2026-0004');
});

test('createCreditNote pads counter with zeros', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote skips non-matching numbers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const existingNumbers = [
    'CN-2025-0099',
    'CN-2027-0050',
    'OTHER-2026-0001',
  ];

  const cn = createCreditNote(r2.value, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, existingNumbers);
  assert.equal(cn.value.number, 'CN-2026-0001');
});

test('createCreditNote with small amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
